(()=>{
'use strict';
const colors={paper:'#f5f5e9',ink:'#354137',muted:'#65705e',line:'#d5d9ca'},cache=new Map();
function safeSource(src){if(typeof src!=='string')throw Error('图片地址缺失');if(/^data:image\/(png|jpeg|webp);base64,/.test(src))return src;const url=new URL(src,location.href);if(!['https:','http:','blob:'].includes(url.protocol))throw Error('图片地址不可用');return url.href;}
function loadImage(src){const url=safeSource(src);if(cache.has(url))return cache.get(url);const promise=new Promise((resolve,reject)=>{const img=new Image();img.crossOrigin='anonymous';const timer=setTimeout(()=>{img.src='';reject(Error('图片加载超时'));},15000);img.onload=()=>{clearTimeout(timer);resolve(img);};img.onerror=()=>{clearTimeout(timer);reject(Error('图片加载失败'));};img.src=url;});cache.set(url,promise);promise.catch(()=>cache.delete(url));return promise;}
async function imageData(src){const img=await loadImage(src),canvas=document.createElement('canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;canvas.getContext('2d').drawImage(img,0,0);return canvas.toDataURL('image/png');}
function blocks(report,comparison){const {phase,counts,rows,contributions,friends,companions,issues}=report,M=window.HerstoryReportModel,b=[];const text=(value,size=32,color=colors.ink,gap=18)=>b.push({type:'text',value,size,color,gap,center:b.length<3||value===phase.copy});
 text(phase.label,30,colors.muted);text(phase.title,56);text(phase.start.replaceAll('-','.')+' — '+phase.end.replaceAll('-','.'),27,colors.muted,25);b.push({type:'image',src:report.snapshot.image_url,height:830});text(phase.copy,30,colors.muted,24);text((report.finalized?'已定稿':'持续更新')+' · 数据截至 '+M.format(report.cutoff)+'（上海时间）',26,colors.muted,32);
 if(counts){b.push({type:'stats',counts});b.push({type:'totals',counts,hostCount:report.hostCount});}else text('活动打卡记录尚未同步',30,colors.muted);
 text('活动足迹',38);for(const group of phase.id==='full'?[['第一周 · 10.19—10.25',rows.filter(r=>r.date<='2026-10-25')],['第二周 · 10.26—11.01',rows.filter(r=>r.date>='2026-10-26')]]:[['',rows]]){if(group[0])text(group[0],30,colors.muted);if(!group[1].length)text(counts?'这段时间暂无有效活动打卡':'活动记录尚未同步',28,colors.muted);for(const r of group[1]){text(r.date.slice(5).replace('-','.')+' · '+M.categories[r.category].label,26,colors.muted,8);text(r.title,34,colors.ink,10);text('打卡成功 · '+M.format(r.checkedAt),25,colors.muted,26);}}
 if(contributions.length){text('社区贡献',38);text('发起并举办 '+contributions.length+' 场'+(report.partnerCount===null?'':' · 实际参与伙伴 '+report.partnerCount+' 人'),30);for(const a of contributions){text(a.title,34);text(a.event_date+' · 已实际举办',26,colors.muted);if(a.partners===null)text('实际参与伙伴待同步',27,colors.muted);else for(const person of a.partners)b.push({type:'person',person});}}
 text(phase.id==='week'?'这一周的相遇':'两周的相遇',38);text(friends===null?'好友记录待同步':'新增好友 '+friends.length+' 位',34);if(companions?.length)text('同行伙伴 '+companions.length+' 位',30,colors.muted);
 if(phase.id==='full'){text('星球的两次留影',38);if(comparison?.length===2){b.push({type:'pair',images:comparison});}else text('同角度的阶段留影待补齐',28,colors.muted);}
 if(issues.length){text('记录说明',30,colors.muted);issues.forEach(issue=>text(issue,25,colors.muted,10));}return b;
}
async function exportReport(report,comparison){if(!report.snapshot)throw Error('阶段留影补齐后可保存');await document.fonts.ready;const list=blocks(report,comparison),images=new Map();const sources=new Set();for(const b of list){if(b.type==='image')sources.add(b.src);if(b.type==='pair')b.images.forEach(x=>sources.add(x.image_url));if(b.type==='person'&&b.person.avatar)sources.add(b.person.avatar);}await Promise.all([...sources].map(async s=>images.set(s,await loadImage(s))));
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');const width=1080,pad=88,content=width-2*pad;canvas.width=width;
 function wrap(str,size,max=content){ctx.font=size+'px "Microsoft YaHei",sans-serif';const lines=[];for(const paragraph of String(str).split('\n')){let line='';for(const char of Array.from(paragraph)){if(line&&ctx.measureText(line+char).width>max){lines.push(line);line=char;}else line+=char;}lines.push(line);}return lines;}
 let height=90;for(const b of list){if(b.type==='text'){b.lines=wrap(b.value,b.size);b.height=b.lines.length*b.size*1.6+b.gap;}else if(b.type==='image')b.height+=32;else if(b.type==='pair')b.height=530;else if(b.type==='stats')b.height=130;else if(b.type==='totals')b.height=160;else{b.lines=wrap(b.person.name,30,content-100);b.height=Math.max(90,b.lines.length*46+20);}height+=b.height;}height=Math.ceil(height+70);if(height>28000)throw Error('记录较多，完整长图需要服务端导出支持');canvas.height=height;ctx.fillStyle=colors.paper;ctx.fillRect(0,0,width,height);let y=80;
 function fit(img,x,y,w,h){const ratio=Math.min(w/img.width,h/img.height);ctx.drawImage(img,x+(w-img.width*ratio)/2,y+(h-img.height*ratio)/2,img.width*ratio,img.height*ratio);}
 for(const b of list){if(b.type==='text'){ctx.font=b.size+'px "Microsoft YaHei",sans-serif';ctx.fillStyle=b.color;ctx.textBaseline='top';b.lines.forEach((line,i)=>ctx.fillText(line,b.center?(width-ctx.measureText(line).width)/2:pad,y+i*b.size*1.6));}else if(b.type==='image')fit(images.get(b.src),pad,y,content,b.height-32);else if(b.type==='pair'){b.images.forEach((img,i)=>{fit(images.get(img.image_url),pad+i*(content/2+12),y,content/2-12,440);ctx.font='25px "Microsoft YaHei",sans-serif';ctx.fillStyle=colors.muted;ctx.fillText(i?'全程结束 · 11.01':'首周结束 · 10.25',pad+i*(content/2+12),y+458);});}else if(b.type==='stats'||b.type==='totals'){ctx.save();ctx.strokeStyle='#d5d9ca';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(pad,y,content,b.height-24,24);ctx.stroke();const cells=b.type==='stats'?Object.entries(window.HerstoryReportModel.categories).map(([id,c])=>({label:c.label,value:b.counts[id],unit:'场',color:c.color})):[{label:'参与',value:b.counts.participated,unit:'场'},{label:'发起',value:b.hostCount??'—',unit:'场'},{label:'打卡',value:b.counts.days,unit:'天'}];cells.forEach((c,i)=>{const center=pad+content*(i+.5)/3;if(i){ctx.beginPath();ctx.moveTo(pad+content*i/3,y+26);ctx.lineTo(pad+content*i/3,y+b.height-50);ctx.stroke();}ctx.textAlign='center';ctx.textBaseline='middle';if(b.type==='stats'){ctx.font='30px sans-serif';ctx.fillStyle=colors.ink;ctx.fillText(c.label+' '+c.value+' '+c.unit,center+8,y+52);ctx.fillStyle=c.color;ctx.beginPath();ctx.arc(center-100,y+52,12,0,Math.PI*2);ctx.fill();}else{ctx.fillStyle=colors.muted;ctx.font='26px sans-serif';ctx.fillText(c.label,center,y+38);ctx.fillStyle='#705528';ctx.font='40px sans-serif';ctx.fillText(c.value+' '+c.unit,center,y+90);}});ctx.restore();}else{ctx.save();ctx.beginPath();ctx.arc(pad+32,y+32,32,0,Math.PI*2);ctx.clip();ctx.fillStyle='#e1e5d9';ctx.fillRect(pad,y,64,64);if(b.person.avatar)fit(images.get(b.person.avatar),pad,y,64,64);else{ctx.fillStyle=colors.ink;ctx.font='28px sans-serif';ctx.textBaseline='middle';ctx.fillText(Array.from(b.person.name)[0]||'·',pad+18,y+33);}ctx.restore();ctx.fillStyle=colors.ink;ctx.font='30px "Microsoft YaHei",sans-serif';ctx.textBaseline='top';b.lines.forEach((line,i)=>ctx.fillText(line,pad+94,y+14+i*46));}y+=b.height;}
 const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('长图生成失败')),'image/png'));return {blob,width,height};
}
async function saveReport(blob,name){
 const file=new File([blob],name,{type:blob.type||'image/png'});
 const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
 if(ios&&typeof navigator.share==='function'&&(!navigator.canShare||navigator.canShare({files:[file]}))){await navigator.share({files:[file]});return;}
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
}
window.HerstoryReportExport={loadImage,imageData,safeSource,exportReport,saveReport};
})();
